import manifestFixture from '../../contract/manifest.json';
import planFixture from '../../contract/plan-response.json';
import { applyCommand, type BlockMap } from '../src/client/optimistic';
import { PlanStore } from '../src/client/store';
import type { Transport } from '../src/client/transport';
import type { Command, CommandSuccess, DeleteImpact, Manifest, PlanResponse } from '../src/client/types';

/** IDs used in contract/plan-response.json (generated by tests/Feature/ContractTest.php). */
export const ids = {
  day1: '01jd0000000000000000000001',
  breakfast: '01jd0000000000000000000002',
  backup: '01jd0000000000000000000003',
  lunch: '01jd0000000000000000000004',
  note: '01jd0000000000000000000005',
  pool: '01jd0000000000000000000006',
  museum: '01jd0000000000000000000007',
  day2: '01jd0000000000000000000008',
  link: '01jd0000000000000000000009',
};

export function planResponse(): PlanResponse {
  return structuredClone(planFixture) as PlanResponse;
}

export function manifest(): Manifest {
  return structuredClone(manifestFixture) as unknown as Manifest;
}

type Handler = (baseVersion: number, commands: Command[]) => Promise<CommandSuccess>;

export class FakeTransport implements Transport {
  sent: Array<{ baseVersion: number; commands: Command[] }> = [];
  impact: DeleteImpact | null = null;
  private server: BlockMap;

  /**
   * Default: behave like the server. Apply the commands to its own copy and
   * return the resulting blocks (derived values are not recalculated).
   */
  handler: Handler = async (baseVersion, commands) => {
    const before = new Set(this.server.keys());
    for (const command of commands) applyCommand(this.server, command, manifest());
    return {
      ok: true,
      version: baseVersion + commands.length,
      full: false,
      blocks: [...this.server.values()],
      deleted: [...before].filter((id) => !this.server.has(id)),
    };
  };

  constructor(public plan: PlanResponse = planResponse()) {
    this.server = new Map(plan.blocks.map((b) => [b.id, structuredClone(b)]));
  }

  async loadPlan(): Promise<PlanResponse> {
    return structuredClone(this.plan);
  }

  async loadManifest(): Promise<Manifest> {
    return manifest();
  }

  send(baseVersion: number, commands: Command[]): Promise<CommandSuccess> {
    this.sent.push({ baseVersion, commands: structuredClone(commands) });
    return this.handler(baseVersion, commands);
  }

  async deleteImpact(blockId: string): Promise<DeleteImpact> {
    return this.impact ?? { block: blockId, descendants: 0, links: [] };
  }
}

export class MemoryStorage {
  items = new Map<string, string>();
  get length() {
    return this.items.size;
  }
  key(index: number) {
    return [...this.items.keys()][index] ?? null;
  }
  getItem(key: string) {
    return this.items.get(key) ?? null;
  }
  setItem(key: string, value: string) {
    this.items.set(key, value);
  }
  removeItem(key: string) {
    this.items.delete(key);
  }
}

export async function makeStore(transport = new FakeTransport(), storage: MemoryStorage | null = new MemoryStorage()) {
  const store = new PlanStore({ transport, storage, retry: { base: 10, max: 50 }, persistence: { locks: null, intervalMs: 30, staleMs: 100 } });
  await store.load();
  return { store, transport, storage };
}

/** Let microtasks, timers and pending promises run. */
export async function settle(ms = 0): Promise<void> {
  for (let i = 0; i < 5; i++) await new Promise((resolve) => setTimeout(resolve, ms));
}

export function deferred<T>() {
  let resolve!: (value: T) => void;
  let reject!: (error: unknown) => void;
  const promise = new Promise<T>((res, rej) => {
    resolve = res;
    reject = rej;
  });
  return { promise, resolve, reject };
}

/** Saved queue entries for a plan: { key: commands }. */
export function savedQueues(storage: MemoryStorage, plan = '01jd00000000000000000000p1'): Record<string, unknown[]> {
  const out: Record<string, unknown[]> = {};
  for (const [key, value] of storage.items) {
    if (key.startsWith(`plan-block:queue:${plan}`)) {
      const data = JSON.parse(value);
      out[key] = Array.isArray(data) ? data : data.commands;
    }
  }
  return out;
}
